insert into menu_items (id, category_id, name_uk, description_uk, price, original_price, promo_label, weight, storage_note, badge, freezable, min_order_override, photo_url, sort_order) values
  ('7e4a7349-8d0b-4d41-8d61-7269e3ed257a', 'c5393b94-8afc-4c79-972b-65e09be734df', 'Наполеон чорничний', 'Наполеон з чорничним кремом на основі заварного крему з вершками та чорницею, декорований лохиною.', 1250, 1500, 'Товар тижня · -15%', '1,7 кг', 'Термін придатності: 4 доби.', null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_ehLxZ-cvlUC-IVXAg.png', 0),
  ('032a1740-851e-4411-b934-5388b75b45f2', 'c5393b94-8afc-4c79-972b-65e09be734df', 'Тарт з малиною', 'Пісочна основа, фісташкова начинка та свіжа малина.', 1050, null, null, '1,33 кг', 'Термін придатності: 3 доби.', null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_wIFnc-IBaHI-GDIPW.jpeg', 1),
  ('f72e5ba8-c91e-4d55-b351-51b9e904654f', 'c5393b94-8afc-4c79-972b-65e09be734df', 'Тарт чорничний з мʼятою', 'Пісочна основа, мʼятний крем на основі білого шоколаду, крем з чорницею та вершками, декорований лохиною.', 980, null, null, '1,13 кг', 'Термін придатності: 3 доби.', null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_IiOSq-GyIqb-uODEG.png', 2),
  ('6d7d64d7-5217-4262-ad3b-6d8e7346970c', 'c5393b94-8afc-4c79-972b-65e09be734df', 'Торт Тропік', 'Вершкові бісквіти, крем манго, конфі маракуя зі шматочками манго, декорований вершками і кюлі маракуя.', 1300, null, null, '1,68 кг', 'Термін придатності: 4 доби.', null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_CVHbG-JGuFl-zdKbK.png', 3),
  ('3fc90169-4c7b-476b-a651-32cd9f76dc8f', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Ягідний йогурт', 'Круглий круасан з листкового тіста. Начинка: йогуртово-ягідний крем. Прикрашений кольоровою глазурʼю і сезонними ягодами.', 125, null, null, '190 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_ASJSH-vLceE-lcxVI.png', 0),
  ('913b106c-197f-425e-bf46-86785f346bf1', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Фісташка-малина', 'Круглий круасан з листкового тіста. Начинка: вершково-фісташковий крем та малинове кюлі. Прикрашений кольоровою глазурʼю, сезонними ягодами та подрібненою фісташкою.', 133, null, null, '180 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_bTFQA-nIFeE-TWUCv.png', 1),
  ('47d425ba-cf20-414e-8315-95b551211d5f', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Вибухова карамель', 'Круглий круасан з листкового тіста. Начинка: крем із солоною карамеллю. Прикрашений карамеллю і солодким попкорном.', 125, null, null, '170 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_qchkp-bLrWH-vfPHB.png', 2),
  ('dcfa301d-e78b-4ebd-b7a2-60a1eed9298c', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Манго-маракуя', 'Круглий круасан з листкового тіста. Начинка: крем зі смаком манго-маракуя. Прикрашений кольоровою глазурʼю, сушеним манго і шоколадною крихтою.', 125, null, null, '180 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_Ctoeb-WoFQg-xSfym.png', 3),
  ('7d074213-6094-4a24-b43f-f1e86c1e18fc', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Шоколадний цитрус', 'Круглий круасан з листкового тіста. Начинка: вершково-шоколадний крем з апельсиново-лимонним курдом. Прикрашений шоколадною глазурʼю і апельсином.', 125, null, null, '190 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_FukqX-eToCs-zrcyz.png', 4),
  ('3049fc0a-0d31-4b86-9039-0eb47967d55d', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Полуниця', 'Круасан-рол з вершковим кремом на основі білого шоколаду та полуничне конфі зі свіжою полуницею. Декорований сублімованими ягодами.', 125, null, null, '190 г', null, 'ОНОВЛЕННЯ ДЕКОРУ', false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_NlJvK-cYdsg-MIPmU.png', 5),
  ('43008e0e-89f8-488f-8cc7-a3dc70edbf2f', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Шоколадний', 'Листкове тісто з вершковим маслом. Начинка: шоколадно-фундучна.', 73, null, null, '136 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_EPDpV-glrco-WsdAP.png', 0),
  ('21d1d7c2-eae3-477a-b91a-7300bb4332e4', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Вишневий', 'Листкове тісто з вершковим маслом. Начинка: цілі шматочки натуральної вишні.', 69, null, null, '136 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_HdLxY-ffsWK-ngiGC.png', 1),
  ('eb3b22b5-cc45-422e-af79-8926824e198d', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Мигдалевий', 'Листкове тісто з вершковим маслом. Начинка: франжипан, в якому багато мигдального борошна з нотками апельсину та коньяку. Прикрашений мигдальними пластівцями.', 83, null, null, '145 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_RdYbF-JBCdP-VhDyO.png', 2),
  ('b451e6ff-21b9-4d40-83b3-115070bc9d22', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Класичний', 'Ніжне і ароматне листкове тісто. Без начинки.', 55, null, null, '95 г', null, null, false, null, null, 3),
  ('7dbee4da-be64-4b61-af00-1b4ff5316476', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Лимонний', 'Ніжне листкове тісто. Начинка: лимонний крем з кислинкою. Прикрашений італійською меренгою.', 99, null, null, '160 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_EFhRG-QONTe-gjFfD.png', 4),
  ('0bb37c6f-d707-4287-8adf-bff505ec7508', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Фісташковий', 'Листкове тісто з вершковим маслом. Начинка: фісташковий крем власного виробництва з фісташковою пастою.', 112, null, null, '165 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_gYfuH-WHeCI-BnIGT.png', 5),
  ('62c69b97-0820-4483-b298-2e663377426a', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Кокосовий', 'Листкове тісто. Начинка: на основі білого шоколаду та кокосового борошна. Прикрашений глазурʼю та кокосовою стружкою.', 99, null, null, '150 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_nmsCG-sCsew-ZFCHY.png', 6),
  ('5f28283c-c913-4e42-a040-a53b3e1ca168', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Йогуртовий', 'Ніжне листкове тісто. Начинка: йогуртова та чорнично-смородинова. Прикрашений сублімованою малиною.', 99, null, null, '170 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_JHRHL-GaNGc-FmoOc.png', 7),
  ('b92fc0a5-e274-4ca9-9c0f-294b5468dbee', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Равлик вишневий', 'Равлик з листкового тіста з корицею та вишневим кюлі. Вкритий вишневим соусом.', 37, null, null, '125 г', null, null, false, 4, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_lJWDI-exDlQ-OULBT.png', 8),
  ('fc56f744-72a4-4ac2-954d-1aa9cb1cc7c3', '89cea3b8-c64e-4d5f-a44f-5dfada37df75', 'Чізкейк Нью-Йорк з солоною карамеллю', 'Класичний чізкейк з ніжним вершковим сиром. Вкритий тягучою солоною карамеллю власного виробництва. Прикрашений сезонними ягодами та мигдальними пластівцями. К-ть шматочків — 10 шт.', 990, null, null, '1,6 кг', null, 'ОНОВЛЕННЯ ДЕКОРУ', false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_DleCr-bIHGB-CCnAi.png', 0),
  ('4e9b1c93-d816-49d6-8d33-aa58391a6298', '89cea3b8-c64e-4d5f-a44f-5dfada37df75', 'Чізкейк Нью-Йорк з солоною карамеллю (шматочок)', 'Шматочок чізкейка Нью-Йорк з солоною карамеллю та сезонними ягодами.', 99, null, null, '160 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_DleCr-bIHGB-CCnAi.png', 1),
  ('70edebb4-b611-44d3-b285-47f8121145bb', '89cea3b8-c64e-4d5f-a44f-5dfada37df75', 'Чізкейк Нью-Йорк', 'Класичний чізкейк. Основа з пісочного тіста. Зроблений з ніжним вершковим сиром. К-ть шматочків — 10 шт.', 890, null, null, '1,4 кг', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_EykUe-JFWIA-PtxuC.jpeg', 2),
  ('55b56fdf-aebd-415e-91e2-67f136b9734c', '89cea3b8-c64e-4d5f-a44f-5dfada37df75', 'Чізкейк Нью-Йорк (шматочок)', 'Шматочок класичного чізкейка Нью-Йорк.', 89, null, null, '140 г', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_EykUe-JFWIA-PtxuC.jpeg', 3),
  ('30af36a9-035e-4766-878c-136a90f21e0a', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Манго-полуниця', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду, натуральне манго, полуничне кюлі. Прикрашений кольоровою глазурʼю, ніжним кремом і сублімованою полуницею.', 79, null, null, '75 г', null, null, true, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_GrXXU-hApPP-PkCpn.png', 0),
  ('c057b3a2-360c-48c2-887b-9920e953b0fd', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Чорниця-лимон', 'Заварне тісто. Начинка: чорничний крем на основі білого шоколаду та вершків, лимонний курд. Прикрашений лохиною і ніжним кремом.', 82, null, null, '100 г', null, null, true, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_KsAFb-qevzu-oFHRF.png', 1),
  ('16168783-84ce-42d1-a5fd-102cc6993154', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Фісташковий', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду, сезонні ягоди. Прикрашений кольоровою глазурʼю та подрібненою фісташкою.', 89, null, null, '70 г', null, null, true, null, 'https://menuorderperemoga.lovable.app/__l5e/assets-v1/1293fd32-3636-42f4-8036-c86dc6ee1937/eclair-pistachio.jpg', 2),
  ('34a07dc1-5ad6-431f-9f54-59f655106af4', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Шоколадний', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду з додаванням чорного шоколаду. Прикрашений кольоровою глазурʼю і ніжним шоколадним кремом.', 79, null, null, '80 г', null, null, true, null, 'https://menuorderperemoga.lovable.app/__l5e/assets-v1/83b3c75d-d409-4a7a-940f-e4a8eb38690b/eclair-chocolate.jpg', 3),
  ('78a11e99-ca1d-4c76-8165-b5490ec6d554', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Солона карамель', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду, солона карамель. Прикрашений кольоровою глазурʼю, горіховою крихтою і солодким попкорном.', 79, null, null, '70 г', null, null, true, null, 'https://menuorderperemoga.lovable.app/__l5e/assets-v1/c6fcd3bd-f1a5-4820-baaa-8e2793fa0b9c/eclair-salted-caramel.jpg', 4),
  ('89ddf91a-85ae-4391-ba1d-f86ecb4e4644', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Малина-мʼята', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду, мʼята та малинове кюлі власного виробництва. Прикрашений кольоровою глазурʼю.', 79, null, null, '70 г', null, null, true, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_QvzqW-wHCKE-sUbHT.png', 5),
  ('9f415678-3647-42da-bc5a-23957db1c272', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Ванільний', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду з ваніллю. Прикрашений кольоровою глазурʼю і ніжним кремом.', 79, null, null, '75 г', null, null, true, null, 'https://menuorderperemoga.lovable.app/__l5e/assets-v1/d78d2345-ebf8-4704-846d-578592e3eaf5/eclair-vanilla.jpg', 6),
  ('772f9823-e293-48da-99eb-c27fac01adb4', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'З полуницею', 'Еклер з подвійною начинкою: ванільним кремом на основі білого шоколаду та полуничним конфі зі свіжою полуницею.', 89, null, null, '100 г', null, null, true, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_sdGLh-mNykM-flsHY.png', 7),
