  ('6ab3ffa0-30f0-4f62-b169-32297df9231e', '62180cd2-9750-466e-a404-64429dc54a69', 'Фісташка — чорниця', 'Білий шоколад, вершки, фісташкова паста. Серединка: кюлі з малини.', 60, null, null, '40-45 г', null, null, false, null, 'https://menuorderperemoga.lovable.app/__l5e/assets-v1/388353c3-5573-4a9c-b991-9a9ac0e8706e/macaron-pistachio-blueberry.jpg', 4),
  ('a488a9f2-fac6-4e3f-a484-079aae564dcf', '62180cd2-9750-466e-a404-64429dc54a69', 'Ваніль — полуниця', 'Білий шоколад, вершки, натуральна ваніль. Серединка: кюлі з полуниці.', 60, null, null, '40-45 г', null, null, false, null, 'https://menuorderperemoga.lovable.app/__l5e/assets-v1/9103313e-e5e6-4248-a036-a7f1964887aa/macaron-vanilla-strawberry.jpg', 5),
