  ('ab7a4ac7-532c-42bf-a447-e19a48e3259c', 'f5d6909f-624b-412a-9309-ba1080d91f6c', 'Гарбузовий', 'Ніжний і ароматний хліб з додаванням пюре гарбуза. Має солодкуватий смак та мʼяку текстуру.', 73, null, null, '0,450 кг', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_ttzUS-TaYbH-lfeRR.jpeg', 2),
