  ('c2ce82b8-8b59-41df-9530-91f6cf2bf1e6', 'f5d6909f-624b-412a-9309-ba1080d91f6c', 'Гречаний бездріжджовий', 'Борошно пшеничне в.г., борошно гречане, клейковина пшенична, вода, закваска пшенична, сіль. Технологія довгої ферментації для кращого засвоєння.', 85, null, null, '0,410 кг', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_LyrWk-FHUDe-WmcgH.png', 4),
  ('a976271c-5965-406a-9ad7-ddfc71ea7d82', 'f5d6909f-624b-412a-9309-ba1080d91f6c', 'Гречаний', 'Хліб, виготовлений з гречаного борошна, має характерний гречаний смак і темний колір.', 65, null, null, '0,480 кг', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_LyrWk-FHUDe-WmcgH.png', 5),
  ('71f04987-705e-4092-9930-bacab2533d8c', 'f5d6909f-624b-412a-9309-ba1080d91f6c', 'Висівковий', 'Виготовляється на заквасці з додаванням житнього, пшеничного борошна з додаванням висівок.', 45, null, null, '0,475 кг', null, null, false, null, 'https://cdn-media.choiceqr.com/prod-eat-peremoga-bakery950/menu/thumbnail_kxrkn-PIqmD-eZecM.jpeg', 6),
