  ('delivery_terms', '{"title": "УМОВИ ДОСТАВКИ", "blocks": [{"heading": "Для м. Києва", "lines": ["Прийом замовлення за день до дня поставки: нд — пт до 17:00", "Доставка замовлень: пн 09:00 — 14:00, ср 09:00 — 14:00, пт 09:00 — 14:00", "Мінімальна сума замовлення — 1 000 грн", "Вартість доставки: правий берег — 200 грн, лівий берег — 250 грн", "При замовленні від 2 000 грн доставка безкоштовна"]}, {"heading": "Для м. Ірпінь, Буча, Білогородка і район Троєщина (м. Київ)", "lines": ["Доставка замовлень по середах 10:00 — 14:00", "Мінімальна сума замовлення — 1 000 грн", "Вартість доставки — 250 грн", "При замовленні від 2 000 грн доставка безкоштовна"]}, {"heading": "Особливі умови", "lines": ["Можливе відтермінування платежу 2–3 дні", "Чат підтримки: пн — пт 10:00 — 17:00, сб — нд 12:30 — 17:00"]}, {"heading": "Форма замовлення", "lines": ["Назва закладу", "Адреса та номер отримувача замовлення", "Вид оплати: ФОП / готівка (якщо ФОП — дані платника)", "+380 96 96 94 485 — Максим"]}, {"heading": "Дегустаційний сет", "lines": ["Партнер може замовити сет з трьох позицій з меню на вибір — ми безкоштовно доставимо дегустаційний сет на локацію!"]}]}'::jsonb);
