-- Real menu catalog, migrated from the existing site's src/data/menuData.ts
-- (16 categories, 90 items). Run this once, after schema.sql, in the Supabase
-- SQL editor. Photos hotlink to the live Lovable site's CDN / asset host for
-- now (both are public, stable URLs) rather than being re-uploaded to the
-- menu-photos storage bucket — re-host them there later if the Lovable app is
-- ever retired.




-- The original site marked these 8 "new" items with a badge of "\n" (its
-- "NEW" label lost in a Lovable edit); restore it as an explicit NEW badge,
-- which the storefront renders as the red new-item marker.
update menu_items m
set badge = 'NEW'
from menu_categories c
where m.category_id = c.id
  and (c.name_uk, m.name_uk) in (
    ('Новинки', 'Наполеон чорничний'),
    ('Новинки', 'Тарт з малиною'),
    ('Новинки', 'Тарт чорничний з мʼятою'),
    ('Новинки', 'Торт Тропік'),
    ('Круглі круасани · New York Rolls', 'Манго-маракуя'),
    ('Еклери', 'Чорниця-лимон'),
    ('Тарти', 'З малиною'),
    ('Донати', 'Лісовий горіх')
  );
